    // ─── Lifecycle ──────────────────────────────────────────────
    protected override async Task OnInitializedAsync()
    {
        _maTruongBo = await BrowserStorageService.GetMaTruongBoAsync(JS);
        _selectedNamHoc = await BrowserStorageService.GetItem(JS, "selectedNamHoc") ?? "";
        _capHoc = await BrowserStorageService.GetItem(JS, "selectedLevel") ?? "1";


        SetCurrentWeek();
        await LoadAll();
    }

    // ─── Data loading ───────────────────────────────────────────
    private async Task LoadAll()
    {
        _isLoading = true;
        StateHasChanged();
        try
        {
            await Task.WhenAll(LoadKhoi(), LoadLop(), LoadTietHoc(), LoadGiaoVien(), LoadTKB());
            AutoSelectFirstKhoi();
            AutoSelectFirstLop();
            ApplyFilter();
        }
        catch (Exception ex) { ShowMsg($"Lỗi tải dữ liệu: {ex.Message}", "danger"); }
        finally { _isLoading = false; StateHasChanged(); }
    }

    private async Task LoadKhoi()
    {
        try { _khoiList = await TruongService.hGetDanhSachKhoi(_maTruongBo, _capHoc); }
        catch { _khoiList = new(); }
    }

    private async Task LoadLop()
    {
        try
        {
            _lopList = await TruongService.hGetDanhSachLop(_maTruongBo, _capHoc, _selectedNamHoc);
            RebuildFilteredLop();
        }
        catch { _lopList = new(); _filteredLopList = new(); }
    }

    private async Task LoadTietHoc()
    {
        try { _tietHocList = await DaoTaoService.hGetTietHoc(); }
        catch { _tietHocList = new(); }
    }

    private async Task LoadGiaoVien()
    {
        try { _giaoVienList = await TruongService.hGetDanhSachGiaoVien(_maTruongBo, _selectedNamHoc); }
        catch { _giaoVienList = new(); }
    }

    private async Task LoadTKB()
    {
        try
        {
            _tkbAll = await DaoTaoService.hGetThoiKhoaBieu();
        }
        catch { _tkbAll = new(); }
    }

    // ─── Filter helpers ─────────────────────────────────────────
    private void RebuildFilteredLop()
    {
        _filteredLopList = string.IsNullOrEmpty(_selectedKhoi)
            ? _lopList.ToList()
            : _lopList.Where(l => l.MaKhoiBo == _selectedKhoi).ToList();
    }

    private void AutoSelectFirstKhoi()
    {
        if (string.IsNullOrEmpty(_selectedKhoi))
        {
            var first = _khoiList.FirstOrDefault();
            if (first != null)
            {
                _selectedKhoi = first.MaKhoiBo ?? "";
                RebuildFilteredLop();
            }
        }
    }

    private void AutoSelectFirstLop()
    {
        if (_selectedLopId <= 0)
        {
            var first = _filteredLopList.FirstOrDefault();
            if (first != null)
            {
                _selectedLopId = first.IdLopBo;
                _selectedLop   = first;
            }
        }
    }

    private void ApplyFilter()
    {
        _tkbFiltered = _selectedLopId > 0
            ? _tkbAll.Where(t => t.IdLopHoc == _selectedLopId).ToList()
            : _tkbAll.ToList();
    }

    // ─── Filter event handlers ──────────────────────────────────
    private async Task OnNamHocChanged(ChangeEventArgs e)
    {
        _selectedNamHoc = e.Value?.ToString() ?? "";
        _selectedKhoi   = "";
        _selectedLopId  = 0;
        _selectedLop    = null;
        _isLoading = true; StateHasChanged();
        await Task.WhenAll(LoadLop(), LoadGiaoVien(), LoadTKB());
        AutoSelectFirstLop();
        ApplyFilter();
        _isLoading = false; StateHasChanged();
    }

    private void OnKhoiChanged(ChangeEventArgs e)
    {
        _selectedKhoi  = e.Value?.ToString() ?? "";
        _selectedLopId = 0; _selectedLop = null;
        RebuildFilteredLop();
        AutoSelectFirstLop();
        ApplyFilter();
    }

    private void OnLopChanged(ChangeEventArgs e)
    {
        if (int.TryParse(e.Value?.ToString(), out int id) && id > 0)
        {
            _selectedLopId = id;
            _selectedLop   = _filteredLopList.FirstOrDefault(l => l.IdLopBo == id);
        }
        else { _selectedLopId = 0; _selectedLop = null; }
        ApplyFilter();
    }

    // ─── Week navigation ────────────────────────────────────────
    private void SetCurrentWeek()
    {
        var t = DateTime.Today;
        _startDate = t.AddDays(-((int)t.DayOfWeek - (int)DayOfWeek.Monday + 7) % 7);
        _endDate   = _startDate.AddDays(5);
    }

    private void PreviousWeek() { _startDate = _startDate.AddDays(-7); _endDate = _endDate.AddDays(-7); }
    private void NextWeek()     { _startDate = _startDate.AddDays(7);  _endDate = _endDate.AddDays(7); }

    // ─── Table data ─────────────────────────────────────────────
    private List<ThoiKhoaBieuDTO> GetCellData(int tietId, DateTime date)
        => _tkbFiltered.Where(t => t.Tiet == tietId && t.Ngay.Date == date.Date).ToList();

    private bool IsNowActive(ThoiKhoaBieuDTO tkb, DaoTaoData.TietHocDTO tiet)
    {
        if (tkb.Ngay.Date != DateTime.Today) return false;
        var now = TimeOnly.FromDateTime(DateTime.Now);
        return now >= tiet.thoigianbatdau && now <= tiet.thoigianketthuc;
    }

    private string GetDayVi(DayOfWeek d) => d switch
    {
        DayOfWeek.Monday    => "Thứ Hai",
        DayOfWeek.Tuesday   => "Thứ Ba",
        DayOfWeek.Wednesday => "Thứ Tư",
        DayOfWeek.Thursday  => "Thứ Năm",
        DayOfWeek.Friday    => "Thứ Sáu",
        DayOfWeek.Saturday  => "Thứ Bảy",
        _                   => "Chủ Nhật"
    };

    private static readonly string[] _palette =
        { "#4f46e5","#10b981","#f59e0b","#ec4899","#8b5cf6","#06b6d4","#ef4444","#84cc16","#f97316" };

    private string GetColor(string name)
        => _palette[Math.Abs(name.GetHashCode()) % _palette.Length];

    // ─── Modal ──────────────────────────────────────────────────
    private void OpenAddModal()
    {
        _form = new TkbForm
        {
            Ngay    = _startDate,
            Tiet    = _tietHocList.FirstOrDefault()?.id_tiethoc ?? 0,
            IdLopBo = _selectedLopId
        };
        _isEditing = false; _editingId = 0; _showDeleteConfirm = false;
        _showModal = true;
    }

    private void OpenAddModalForCell(int tietId, DateTime date)
    {
        _form = new TkbForm
        {
            Ngay    = date,
            Tiet    = tietId,
            IdLopBo = _selectedLopId
        };
        _isEditing = false; _editingId = 0; _showDeleteConfirm = false;
        _showModal = true;
    }

    private void OpenEditModal(ThoiKhoaBieuDTO tkb)
    {
        _form = new TkbForm
        {
            Ngay       = tkb.Ngay,
            Tiet       = tkb.Tiet,
            IdLopBo    = tkb.IdLopHoc,
            TenMonHoc  = tkb.TenMonHoc  ?? "",
            MaGiaoVien = tkb.MaGiaoVienSo ?? ""
        };
        _isEditing = true; _editingId = tkb.IdTKB; _showDeleteConfirm = false;
        _showModal = true;
    }

    private void CloseModal() { _showModal = false; _showDeleteConfirm = false; }

    private async Task SaveForm()
    {
        if (_form.Tiet    <= 0) { ShowMsg("Vui lòng chọn tiết học!",  "warning"); return; }
        if (_form.IdLopBo <= 0) { ShowMsg("Vui lòng chọn lớp học!",   "warning"); return; }

        _isSaving = true;
        try
        {
            // TODO: gọi DaoTaoService.SaveThoiKhoaBieu khi service đã có
            await Task.Delay(350);
            ShowMsg(_isEditing ? "Cập nhật thành công!" : "Thêm mới thành công!", "success");
            CloseModal();
            await LoadTKB();
            ApplyFilter();
        }
        catch (Exception ex) { ShowMsg($"Lỗi: {ex.Message}", "danger"); }
        finally { _isSaving = false; StateHasChanged(); }
    }

    private async Task ConfirmDelete()
    {
        _showDeleteConfirm = false;
        try
        {
            // TODO: gọi DaoTaoService.DeleteThoiKhoaBieu(_editingId) khi service đã có
            await Task.Delay(300);
            ShowMsg("Xóa thành công!", "success");
            CloseModal();
            await LoadTKB();
            ApplyFilter();
        }
        catch (Exception ex) { ShowMsg($"Lỗi xóa: {ex.Message}", "danger"); }
        StateHasChanged();
    }

    // ─── Alert ──────────────────────────────────────────────────
    private void ShowMsg(string msg, string type)
    {
        _message = msg; _messageClass = type;
        StateHasChanged();
        _ = Task.Delay(5000).ContinueWith(_ =>
            InvokeAsync(() => { if (_message == msg) ClearMessage(); }));
    }

    private void ClearMessage() { _message = ""; StateHasChanged(); }

    // ─── IMPORT EXCEL STATE ──────────────────────────────────────
    private bool   _showImportModal    = false;
    private int    _importStep         = 1;
    private string _importError        = "";
    private int    _importSuccessCount = 0;
    private List<ImportRow> _importRows = new();

    private record ImportRow(
        DateTime Ngay,
        int      TietSo,
        int      IdTietHoc,
        string   TenLop,
        int      IdLopBo,
        string   TenMonHoc,
        string   TenGiaoVien,
