        bool     IsValid,
        bool     IsDuplicate,
        string   Error
    );

    // ─── IMPORT MODAL ─────────────────────────────────────────
    private void ShowImportModal()
    {
        _importStep         = 1;
        _importRows         = new();
        _importError        = "";
        _importSuccessCount = 0;
        _showImportModal    = true;
    }

    private void CloseImportModal() => _showImportModal = false;

    // Dùng thay cho inline lambda có escaped quote (không hợp lệ trong Razor)
    private void ResetImport() { _importStep = 1; _importError = ""; }

    // ─── ON FILE SELECTED ─────────────────────────────────────
    private async Task OnFileSelected(InputFileChangeEventArgs e)
    {
        _importError = "";
        var file = e.File;
        if (file == null) return;

        if (!file.Name.EndsWith(".xlsx", StringComparison.OrdinalIgnoreCase) &&
            !file.Name.EndsWith(".xls",  StringComparison.OrdinalIgnoreCase))
        {
            _importError = "Chỉ chấp nhận file .xlsx hoặc .xls";
            StateHasChanged();
            return;
        }

        try
        {
            using var ms = new System.IO.MemoryStream();
            await file.OpenReadStream(maxAllowedSize: 5 * 1024 * 1024).CopyToAsync(ms);
            ms.Position = 0;

            ExcelPackage.LicenseContext = LicenseContext.NonCommercial;
            using var ep    = new ExcelPackage(ms);
            var sheet = ep.Workbook.Worksheets[0];

            if (sheet == null || sheet.Dimension == null || sheet.Dimension.Rows < 2)
            {
                _importError = "File không hợp lệ hoặc không có dữ liệu!";
                StateHasChanged();
                return;
            }

            // Build lookup: tên tiết → TietHocDTO
            var tietByName = _tietHocList
                .GroupBy(t => t.tiet_hoc.ToString())
                .ToDictionary(g => g.Key, g => g.First(), StringComparer.OrdinalIgnoreCase);

            // Build lookup: tên lớp → LopHoc_DTO
            var lopByName = _lopList
                .GroupBy(l => l.TenLop?.Trim() ?? "")
                .ToDictionary(g => g.Key, g => g.First(), StringComparer.OrdinalIgnoreCase);

            // Build lookup: tên GV → MaSo
            var gvByName = _giaoVienList
                .GroupBy(g => g.HoTen?.Trim() ?? "")
                .ToDictionary(g => g.Key, g => g.First(), StringComparer.OrdinalIgnoreCase);

            // Existing TKB keys for duplicate check
            var existKeys = new HashSet<(DateTime, int, int)>(
                _tkbAll.Select(t => (t.Ngay.Date, t.Tiet, t.IdLopHoc)));

            _importRows = new();
            int totalRows = sheet.Dimension.Rows;

            for (int r = 2; r <= totalRows; r++) // bỏ header hàng 1
            {
                // Cột A: Ngày học
                var ngayCell = sheet.Cells[r, 1];
                if (string.IsNullOrWhiteSpace(ngayCell.Text) && ngayCell.Value == null)
                    continue; // dòng trống

                if (!TryParseFlexibleDate(ngayCell, out var ngay))
                {
                    _importRows.Add(new ImportRow(DateTime.MinValue, 0, 0, "", 0, "", "", "",
                        false, false, $"Cột A dòng {r}: không đọc được ngày '{ngayCell.Text}'"));
                    continue;
                }

                // Cột B: Tiết số
                var tietText = sheet.Cells[r, 2].Text?.Trim() ?? "";
                if (!int.TryParse(tietText, out int tietSo) || tietSo <= 0)
                {
                    _importRows.Add(new ImportRow(ngay, 0, 0, "", 0, "", "", "",
                        false, false, $"Cột B dòng {r}: tiết số không hợp lệ '{tietText}'"));
                    continue;
                }

                // Map tên tiết → IdTietHoc
                var tietDto = _tietHocList.FirstOrDefault(t => t.tiet_hoc == tietSo);
                int idTietHoc = tietDto?.id_tiethoc ?? 0;

                // Cột C: Tên lớp
                var tenLop = sheet.Cells[r, 3].Text?.Trim() ?? "";
                if (string.IsNullOrEmpty(tenLop))
                {
                    _importRows.Add(new ImportRow(ngay, tietSo, idTietHoc, "", 0, "", "", "",
                        false, false, $"Cột C dòng {r}: tên lớp trống"));
                    continue;
                }

                lopByName.TryGetValue(tenLop, out var lopDto);
                int idLopBo = lopDto?.IdLopBo ?? 0;

                if (idLopBo == 0)
                {
                    _importRows.Add(new ImportRow(ngay, tietSo, idTietHoc, tenLop, 0, "", "", "",
                        false, false, $"Không tìm thấy lớp '{tenLop}'"));
                    continue;
                }

                // Cột D: Môn học
                var tenMonHoc = sheet.Cells[r, 4].Text?.Trim() ?? "";
                if (string.IsNullOrEmpty(tenMonHoc))
                {
                    _importRows.Add(new ImportRow(ngay, tietSo, idTietHoc, tenLop, idLopBo, "", "", "",
                        false, false, $"Cột D dòng {r}: môn học trống"));
                    continue;
                }

                // Cột E: Giáo viên (tuỳ chọn)
                var tenGv  = sheet.Cells[r, 5].Text?.Trim() ?? "";
                string maGv = "";
                if (!string.IsNullOrEmpty(tenGv) && gvByName.TryGetValue(tenGv, out var gvDto))
                    maGv = gvDto.MaSo ?? "";

                // Check duplicate
                bool dup = existKeys.Contains((ngay.Date, tietSo, idLopBo));

                _importRows.Add(new ImportRow(
                    ngay, tietSo, idTietHoc, tenLop, idLopBo,
                    tenMonHoc, tenGv, maGv,
                    true, dup, ""));
            }

            if (_importRows.Count == 0)
            {
                _importError = "Không đọc được dữ liệu hợp lệ từ file!";
                StateHasChanged();
                return;
            }

            _importStep = 2;
        }
        catch (Exception ex)
        {
            Console.WriteLine(ex);
            _importError = "Đã xảy ra lỗi khi đọc file, vui lòng kiểm tra định dạng!";
        }
        StateHasChanged();
    }

    // ─── EXECUTE IMPORT ──────────────────────────────────────────
    private async Task ExecuteImport()
    {
        var toAdd = _importRows.Where(r => r.IsValid && !r.IsDuplicate).ToList();
        if (!toAdd.Any()) return;

        _isSaving = true;
        StateHasChanged();
        try
        {
            int ok = 0;
            foreach (var row in toAdd)
            {
                try
                {
                    // TODO: thay bằng DaoTaoService.hSaveThoiKhoaBieu khi service có sẵn
                    // bool res = await DaoTaoService.hSaveThoiKhoaBieu(
                    //     _maTruongBo, row.IdLopBo, row.IdTietHoc,
                    //     row.TietSo, row.Ngay, row.TenMonHoc, row.MaGiaoVien);
                    // if (res) ok++;

                    // Stub: giả lập thành công để test UI
                    await Task.Delay(20);
                    ok++;
                }
                catch { /* ghi log nhưng tiếp tục */ }
            }

            _importSuccessCount = ok;
            _importStep = 3;

            // Reload TKB
            await LoadTKB();
            ApplyFilter();
        }
        catch (Exception ex)
        {
            Console.WriteLine(ex);
            ShowMsg("Đã xảy ra lỗi khi import, vui lòng thử lại!", "danger");
        }
        finally
        {
            _isSaving = false;
            StateHasChanged();
        }
    }

    // ─── DOWNLOAD TEMPLATE ───────────────────────────────────────
    private async Task DownloadTemplate()
    {
        try
        {
            ExcelPackage.LicenseContext = LicenseContext.NonCommercial;
            using var ep = new ExcelPackage();
            var ws = ep.Workbook.Worksheets.Add("ThoiKhoaBieu");

            // ── Tiêu đề ──
            ws.Cells[1, 1].Value = "THỜI KHÓA BIỂU — FILE MẪU IMPORT";
            ws.Cells[1, 1, 1, 5].Merge = true;
            ws.Cells[1, 1].Style.Font.Bold = true;
            ws.Cells[1, 1].Style.Font.Size = 13;
            ws.Cells[1, 1].Style.HorizontalAlignment = ExcelHorizontalAlignment.Center;
            ws.Cells[1, 1].Style.Fill.PatternType = ExcelFillStyle.Solid;
            ws.Cells[1, 1].Style.Fill.BackgroundColor.SetColor(System.Drawing.Color.FromArgb(79, 70, 229));
            ws.Cells[1, 1].Style.Font.Color.SetColor(System.Drawing.Color.White);

            // ── Header hàng 2 ──
            string[] headers = { "Ngày học", "Tiết số", "Tên lớp", "Môn học", "Giáo viên (tùy chọn)" };
            for (int c = 0; c < headers.Length; c++)
            {
                ws.Cells[2, c + 1].Value = headers[c];
                ws.Cells[2, c + 1].Style.Font.Bold = true;
                ws.Cells[2, c + 1].Style.Fill.PatternType = ExcelFillStyle.Solid;
                ws.Cells[2, c + 1].Style.Fill.BackgroundColor.SetColor(System.Drawing.Color.FromArgb(224, 231, 255));
                ws.Cells[2, c + 1].Style.Border.BorderAround(ExcelBorderStyle.Thin);
            }

            // ── Dữ liệu mẫu (3 dòng) ──
            var today = DateTime.Today;
            var mon   = today.AddDays(-((int)today.DayOfWeek - (int)DayOfWeek.Monday + 7) % 7);

            var sampleLop = _filteredLopList.FirstOrDefault()?.TenLop ?? "1A";
            var sampleGv  = _giaoVienList.FirstOrDefault()?.HoTen ?? "Nguyễn Văn A";

            object[,] samples =
            {
                { mon.ToString("dd/MM/yyyy"),            1, sampleLop, "Toán",     sampleGv },
                { mon.AddDays(1).ToString("dd/MM/yyyy"), 2, sampleLop, "Tiếng Việt", sampleGv },
                { mon.AddDays(2).ToString("dd/MM/yyyy"), 3, sampleLop, "Khoa học",  "" },
            };

            for (int r = 0; r < 3; r++)
                for (int c = 0; c < 5; c++)
                {
                    ws.Cells[r + 3, c + 1].Value = samples[r, c];
                    ws.Cells[r + 3, c + 1].Style.Border.BorderAround(ExcelBorderStyle.Thin,
                        System.Drawing.Color.FromArgb(209, 213, 219));
                }

            // ── Ghi chú ──
            ws.Cells[7, 1].Value = "Ghi chú: Ngày học định dạng dd/MM/yyyy — Tiết số là số nguyên (1, 2, 3...) — Tên lớp và môn học bắt buộc";
            ws.Cells[7, 1, 7, 5].Merge = true;
            ws.Cells[7, 1].Style.Font.Italic = true;
            ws.Cells[7, 1].Style.Font.Color.SetColor(System.Drawing.Color.Gray);

            // ── Cột của các tiết học sẵn có ──
            if (_tietHocList.Any())
            {
                ws.Cells[9, 1].Value = "Danh sách tiết học:";
                ws.Cells[9, 1].Style.Font.Bold = true;
                for (int i = 0; i < _tietHocList.Count; i++)
                {
                    var t = _tietHocList[i];
                    ws.Cells[10 + i, 1].Value = $"Tiết {t.tiet_hoc}: {t.thoigianbatdau:HH:mm}–{t.thoigianketthuc:HH:mm}";
                }
            }

            // ── Column widths ──
            ws.Column(1).Width = 16;
            ws.Column(2).Width = 10;
            ws.Column(3).Width = 14;
            ws.Column(4).Width = 20;
            ws.Column(5).Width = 24;

            var bytes    = ep.GetAsByteArray();
            var base64   = Convert.ToBase64String(bytes);
            var fileName = $"MauTKB_{DateTime.Today:ddMMyyyy}.xlsx";
            await JS.InvokeVoidAsync("downloadFileFromBase64", fileName, base64);
        }
        catch (Exception ex)
        {
            Console.WriteLine(ex);
            ShowMsg("Đã xảy ra lỗi khi tạo file mẫu!", "danger");
        }
    }

    // ─── FLEXIBLE DATE PARSER (giống TB_ThucDonTuan) ─────────────
    private static bool TryParseFlexibleDate(ExcelRange cell, out DateTime result)
    {
        result = DateTime.MinValue;

        // 1. Ô Excel kiểu DateTime
        if (cell.Value is DateTime dtVal)       { result = dtVal.Date; return true; }

        // 2. OADate (double)
        if (cell.Value is double dblVal && dblVal > 0)
        {
            try { result = DateTime.FromOADate(dblVal).Date; return true; }
            catch { }
        }

        var text = cell.Text?.Trim();
        if (string.IsNullOrEmpty(text)) return false;

        // 3. TryParseExact với nhiều format
        var formats = new[]
        {
            "dd/MM/yyyy", "d/M/yyyy", "dd/MM/yy", "d/M/yy",
            "yyyy-MM-dd", "yyyy/MM/dd",
            "MM/dd/yyyy", "M/d/yyyy",
            "MM-dd-yyyy", "dd-MM-yyyy", "dd.MM.yyyy",
        };

        if (DateTime.TryParseExact(text, formats,
            System.Globalization.CultureInfo.InvariantCulture,
            System.Globalization.DateTimeStyles.None, out var parsed))
        { result = parsed.Date; return true; }

        // 4. Fallback vi-VN rồi Invariant
        var vi = new System.Globalization.CultureInfo("vi-VN");
        if (DateTime.TryParse(text, vi, System.Globalization.DateTimeStyles.None, out var vn))
        { result = vn.Date; return true; }

        if (DateTime.TryParse(text, System.Globalization.CultureInfo.InvariantCulture,
            System.Globalization.DateTimeStyles.None, out var iv))
        { result = iv.Date; return true; }

        return false;
    }

